import{j as a}from"./index-DWMZ50GV.js";const r="Политика обработки персональных данных WayYaam",l="Редакция 1.0 от 31 июля 2026 года. Оператор: Абдулкадыров Дук-Ваха Магомедович, адрес: ул. Т. Л. Алиева, 69 (полный адрес подлежит уточнению), email: studiacatalog@outlook.com.",s=[{title:"1. Сфера действия",paragraphs:["Политика применяется к сайту wayyaam.ru, PWA, заказам, личным кабинетам, доставке, поддержке и пользователям: клиентам, представителям заведений, водителям и администраторам.","Публикация политики не заменяет отдельное согласие, когда оно требуется законом."]},{title:"2. Данные клиентов",items:["имя, телефон, данные аккаунта и сессии","адрес, подъезд, этаж, квартира, домофон, ориентир и комментарий","координаты, точность геолокации, история и состав заказов","избранное, обращения, IP, user-agent и технические события"]},{title:"3. Данные заведений и водителей",items:["представитель заведения: ФИО, email, телефон, полномочия и договорные сведения","заведение: адрес, контакты, меню, фотографии, режим, заказы, расчёты и реквизиты","водитель: ФИО, телефон, email, фото, автомобиль, госномер, зона и геолокация во время работы, доставки и выплаты"]},{title:"4. Цели и основания",paragraphs:["Данные используются для регистрации и безопасности аккаунта, оформления и исполнения заказа/доставки, поддержки, расчётов, выполнения закона и защиты прав. Основания: договоры и оферты, законные обязанности и отдельные согласия.","Рекламные уведомления направляются только по отдельному предварительному согласию; отказ не влияет на регистрацию или заказ."]},{title:"5. Получатели",paragraphs:["Минимальные данные заказа получает выбранный ресторан, назначенный водитель и уполномоченная поддержка. Им запрещено использовать сведения для посторонних целей.","Иностранные сервисы, включая WhatsApp, карты, маршрутизацию и push-провайдеров, могут использоваться только после выполнения требований к локализации и трансграничной передаче. Основная база, Auth, файлы и резервные копии должны находиться в России."]},{title:"6. Геолокация",paragraphs:["Клиент передаёт точку явным действием и может ввести адрес вручную. Геолокация водителя собирается только в online-режиме и/или при активной доставке, доступна участникам этой доставки и прекращается после её окончания."]},{title:"7. Хранение и удаление",paragraphs:["Данные хранятся не дольше целей и обязательных сроков. Сессии ограничиваются сроком; адреса хранятся до удаления пользователем/аккаунтом; точная геолокация минимизируется после доставки; резервные копии удаляются ротацией.","Самостоятельного удаления аккаунта пока нет. Запрос направляется на studiacatalog@outlook.com; оператор проверяет личность, блокирует необязательную обработку, удаляет данные и сообщает результат. Законно обязательные записи отделяются и закрываются для обычного доступа."]},{title:"8. Cookies и данные устройства",paragraphs:["Необходимые технологии обеспечивают вход, корзину и PWA. Аналитические cookies выключены до выбора пользователя. Подробный состав, localStorage, IndexedDB и Cache Storage указан в отдельной Политике cookies."]},{title:"9. Права субъекта",items:["получить сведения и копию обрабатываемых данных","потребовать уточнения, блокирования или уничтожения","отозвать согласие и немедленно отказаться от рекламы","обжаловать действия оператору, Роскомнадзору или в суд"]},{title:"10. Защита и инциденты",paragraphs:["Оператор применяет разграничение доступа, журналирование, защиту каналов и резервных копий, контроль подрядчиков и регламент инцидентов. При применимом инциденте Роскомнадзор уведомляется в сроки закона."]},{title:"11. Будущие сервисы",paragraphs:["Firebase, Sentry, внешняя аналитика, SMS и платёжные системы не считаются подключёнными. До их активации оператор проводит отдельную оценку, обновляет документы и уведомления и получает согласие, когда это требуется."]},{title:"12. Контакт и полная версия",paragraphs:["Запросы: studiacatalog@outlook.com. Полная версия со сроками, таблицами целей и получателей опубликована в юридическом разделе сайта. До запуска оператор обязан заполнить полный адрес и подтвердить российскую инфраструктуру."]}];function p(){return a.jsx("main",{className:"privacy-page",children:a.jsxs("article",{className:"privacy-document",children:[a.jsx("h1",{children:r}),a.jsx("p",{children:l}),s.map(t=>{var i;return a.jsxs("section",{children:[a.jsx("h2",{children:t.title}),(i=t.paragraphs)==null?void 0:i.map(e=>a.jsx("p",{children:e},e)),t.items&&a.jsx("ul",{children:t.items.map(e=>a.jsx("li",{children:e},e))})]},t.title)})]})})}export{p as PrivacyPage};
